    requiredForPlacement: "potrebný na umiestnenie domu na pozemok",
    modularAdvantage: "Výhoda modulárnej konštrukcie:",
    modularAdvantageDesc: "Tento dom je ideálnou voľbou pre tých, ktorí hľadajú praktické, ale štýlové bývanie s jednoduchou inštaláciou a okamžitou pripravenosťou na užívanie. Vďaka premyslenému dizajnu, kvalitným materiálom a možnostiam prispôsobenia je vhodný ako pre menšie rodiny, tak aj pre ľudí, ktorí hľadajú pokojné miesto na odpočinok mimo mesta.\n\nCena nezahŕňa dopravu, základy, vonkajšie prípojky ani služby žeriavu potrebné na vykládku domu.\n\nVšetky naše domy sú navrhnuté tak, aby ich bolo možné jednoducho prepraviť po celej EÚ v plne dokončenom stave. Po dodaní si zákazník iba vyloží dom zo žeriavu, osadí ho na pripravený základ (pri jednomodulových domoch nie je potrebný pevný základ), pripojí prípojky a môže ho okamžite začať využívať. Jediné, čo ostáva, je doviesť si obľúbený nábytok a zariadenie podľa vlastného vkusu.\n\nTieto domy sú ideálnou voľbou pre rodiny, ktoré hľadajú praktické, okamžite obývateľné riešenie s možnosťou mobility. Zároveň sú skvelou alternatívou pre seniorov, ktorí túžia po útulnom mieste mimo mesta – ideálnom na oddych a pohodové bývanie.\n\nVďaka kvalitným materiálom, úsporným riešeniam a jednoduchému usporiadaniu je tento dom navrhnutý tak, aby vyhovoval potrebám každého, kto hľadá komfortný a zároveň prístupný spôsob bývania.\n\nVnútorné rozdelenie izieb, typ vonkajšej omietky a vnútorné obloženie stien sa dá voľne meniť.",
    
