    modularAdvantage: "Avantage de la construction modulaire:",
    modularAdvantageDesc: "Cette maison est le choix idéal pour ceux qui recherchent une vie pratique mais élégante avec une installation simple et une disponibilité immédiate pour l'utilisation. Grâce à une conception réfléchie, des matériaux de qualité et des possibilités de personnalisation, elle convient aussi bien aux petites familles qu'aux personnes recherchant un endroit calme pour se détendre en dehors de la ville.\n\nLe prix ne comprend pas le transport, les fondations, les raccordements externes ni les services de grue nécessaires au déchargement de la maison.\n\nToutes nos maisons sont conçues de manière à pouvoir être facilement transportées dans toute l'UE dans un état entièrement achevé. Après la livraison, le client décharge simplement la maison de la grue, la monte sur une fondation préparée (les maisons à module unique ne nécessitent pas de fondation solide), raccorde les services publics et peut immédiatement commencer à l'utiliser. La seule chose qui reste est d'apporter vos meubles et équipements préférés selon votre propre goût.\n\nCes maisons sont le choix idéal pour les familles recherchant une solution pratique et immédiatement habitable avec possibilité de mobilité. Elles constituent également une excellente alternative pour les seniors qui aspirent à un endroit confortable en dehors de la ville – idéal pour la détente et la vie confortable.\n\nGrâce à des matériaux de qualité, des solutions économiques et une disposition simple, cette maison est conçue pour répondre aux besoins de tous ceux qui recherchent un mode de vie confortable et accessible.\n\nLa division interne des pièces, le type de plâtre extérieur et le revêtement mural intérieur peuvent être librement modifiés.",
    
