    modularAdvantage: "Предност модуларне конструкције:",
    modularAdvantageDesc: "Ова кућа је идеалан избор за оне који траже практичан, али стилски живот са једноставном инсталацијом и тренутном спремношћу за употребу. Захваљујући промишљеном дизајну, квалитетним материјалима и могућностима прилагођавања, погодна је и за мање породице и за људе који траже мирно место за одмор изван града.\n\nЦена не укључује транспорт, темеље, спољне везе нити услуге дизалице потребне за истовар куће.\n\nСве наше куће су дизајниране тако да се могу лако транспортовати широм ЕУ у потпуно завршеном стању. Након испоруке, купац само истовара кућу из дизалице, поставља је на припремљени темељ (једномодулне куће не захтевају чврсти темељ), прикључује везе и може одмах да почне да користи. Једино што преостаје је да донесете омиљени намештај и опрему према сопственом укусу.\n\nОве куће су идеалан избор за породице које траже практично, одмах стамбено решење са могућношћу мобилности. Истовремено су одлична алтернатива за сениоре који желе пријатно место изван града – идеално за одмор и удобан живот.\n\nЗахваљујући квалитетним материјалима, штедљивим решењима и једноставном распореду, ова кућа је дизајнирана тако да задовољи потребе свакога ко тражи удобан а истовремено приступачан начин живота.\n\nУнутрашња подела соба, тип спољашње малтера и унутрашњег облагања зидова могу се слободно мењати.",
    
