    modularAdvantageDesc: "Ova kuća je idealan izbor za one koji traže praktičan, ali stilski život sa jednostavnom instalacijom i trenutnom spremnosti za upotrebu. Zahvaljujući promišljenom dizajnu, kvalitetnim materijalima i mogućnostima prilagođavanja, pogodna je i za manje obitelji i za ljude koji traže mirno mjesto za odmor izvan grada.\n\nCijena ne uključuje transport, temelje, vanjske veze niti usluge dizalice potrebne za istovar kuće.\n\nSve naše kuće su dizajnirane tako da se mogu lako transportovati širom EU u potpuno završenom stanju. Nakon isporuke, kupac samo istovara kuću iz dizalice, postavlja je na pripremljeni temelj (jednomodulne kuće ne zahtijevaju čvrsti temelj), priključuje veze i može odmah početi koristiti. Jedino što preostaje je da donesete omiljeni namještaj i opremu prema vlastitom ukusu.\n\nOve kuće su idealan izbor za obitelji koje traže praktično, odmah stambeno rješenje sa mogućnošću mobilnosti. Istovremeno su odlična alternativa za seniore koji žele prijatno mjesto izvan grada – idealno za odmor i udoban život.\n\nZahvaljujući kvalitetnim materijalima, štedljivim rješenjima i jednostavnom rasporedu, ova kuća je dizajnirana tako da zadovolji potrebe svakoga tko traži udoban a istovremeno pristupačan način života.\n\nUnutrašnja podjela soba, tip vanjske žbuke i unutarnjeg oblaženja zidova mogu se slobodno mijenjati.",
    
