    foundations: "Θεμέλια",
    singleModuleNoFoundations: "μονομοντελικά σπίτια δεν απαιτούν \"τούβλινα\" θεμέλια",
    externalConnections: "Εξωτερικές συνδέσεις",
    waterElectricSewage: "(συνδέσεις νερού, ρεύματος, αποχέτευσης)",
    craneTruck: "Αυτογερανός για εκφόρτωση",
    requiredForPlacement: "απαιτείται για την τοποθέτηση του σπιτιού στο οικόπεδο",
    modularAdvantage: "Πλεονέκτημα της προκατασκευασμένης κατασκευής:",
    modularAdvantageDesc: "Αυτό το σπίτι είναι η ιδανική επιλογή για όσους αναζητούν πρακτική αλλά κομψή διαβίωση με εύκολη εγκατάσταση και άμεση ετοιμότητα για χρήση. Χάρη στον προσεκτικό σχεδιασμό, τα ποιοτικά υλικά και τις δυνατότητες προσαρμογής, είναι κατάλληλο τόσο για μικρότερες οικογένειες όσο και για άτομα που αναζητούν ένα ήσυχο μέρος για ξεκούραση εκτός πόλης.\n\nΗ τιμή δεν περιλαμβάνει μεταφορά, θεμέλια, εξωτερικές συνδέσεις ή υπηρεσίες γερανού που απαιτούνται για την εκφόρτωση του σπιτιού.\n\nΌλα τα σπίτια μας είναι σχεδιασμένα έτσι ώστε να μπορούν να μεταφερθούν εύκολα σε ολόκληρη την ΕΕ σε πλήρως ολοκληρωμένη κατάσταση. Μετά την παράδοση, ο πελάτης απλώς εκφορτώνει το σπίτι από τον γερανό, το τοποθετεί σε προετοιμασμένο θεμέλιο (τα σπίτια ενός module δεν απαιτούν στερεό θεμέλιο), συνδέει τις παροχές και μπορεί αμέσως να αρχίσει να το χρησιμοποιεί. Το μόνο που απομένει είναι να φέρετε τα αγαπημένα σας έπιπλα και εξοπλισμό σύμφωνα με το δικό σας γούστο.\n\nΑυτά τα σπίτια είναι η ιδανική επιλογή για οικογένειες που αναζητούν πρακτική, άμεσα κατοικήσιμη λύση με δυνατότητα κινητικότητας. Είναι επίσης μια εξαιρετική εναλλακτική λύση για ηλικιωμένους που λαχταρούν ένα άνετο μέρος εκτός πόλης – ιδανικό για ανάπαυση και άνετη διαβίωση.\n\nΧάρη στα ποιοτικά υλικά, τις οικονομικές λύσεις και την απλή διάταξη, αυτό το σπίτι έχει σχεδιαστεί έτσι ώστε να καλύπτει τις ανάγκες όλων όσων αναζητούν έναν άνετο και ταυτόχρονα προσιτό τρόπο διαβίωσης.\n\nΗ εσωτερική διαίρεση των δωματίων, ο τύπος του εξωτερικού σοβά και η εσωτερική επένδυση τοίχων μπορούν να αλλάξουν ελεύθερα.",
    
