    importantBasePriceExcludes: "WAŻNE - Cena modelu podstawowego bez konfiguracji NIE zawiera:",
    deliveryTransport: "Dostawa i transport",
    orderInConfigurator: "możliwość zamówienia w konfiguratorze",
    foundations: "Fundamenty",
    singleModuleNoFoundations: "domy jednomodułowe nie wymagają \"murowanych\" fundamentów",
    externalConnections: "Przyłącza zewnętrzne",
    waterElectricSewage: "(przyłącza wody, prądu, kanalizacji)",
    craneTruck: "Dźwig samochodowy do rozładunku",
    requiredForPlacement: "wymagany do ustawienia domu na działce",
    modularAdvantage: "Zaleta konstrukcji modułowej:",
    modularAdvantageDesc: "Ten dom jest idealnym wyborem dla tych, którzy szukają praktycznego, ale stylowego zamieszkania z prostą instalacją i natychmiastową gotowością do użytkowania. Dzięki przemyślanemu projektowi, jakościowym materiałom i możliwościom dostosowania, jest odpowiedni zarówno dla mniejszych rodzin, jak i dla osób poszukujących spokojnego miejsca na odpoczynek poza miastem.\n\nCena nie obejmuje transportu, fundamentów, przyłączy zewnętrznych ani usług dźwigu potrzebnych do rozładowania domu.\n\nWszystkie nasze domy są zaprojektowane tak, aby można je było łatwo transportować po całej UE w pełni wykończonym stanie. Po dostawie klient tylko rozładowuje dom z dźwigu, osadza go na przygotowanym fundamencie (domy jednomodułowe nie wymagają solidnego fundamentu), podłącza przyłącza i może natychmiast zacząć użytkować. Jedyne, co pozostaje, to przywieźć ulubione meble i wyposażenie według własnego gustu.\n\nTe domy są idealnym wyborem dla rodzin poszukujących praktycznego, natychmiast mieszkalnego rozwiązania z możliwością mobilności. Są również świetną alternatywą dla seniorów, którzy pragną przytulnego miejsca poza miastem – idealnego na odpoczynek i wygodne życie.\n\nDzięki jakościowym materiałom, oszczędnym rozwiązaniom i prostemu układowi, ten dom jest zaprojektowany tak, aby sprostać potrzebom każdego, kto szuka wygodnego, a jednocześnie dostępnego sposobu życia.\n\nWewnętrzny podział pokoi, rodzaj tynku zewnętrznego i wewnętrzna okładzina ścian mogą być swobodnie zmieniane.",
    
