    singleModuleNoFoundations: "одномодульні будинки не потребують \"мурованого\" фундаменту",
    externalConnections: "Зовнішні підключення",
    waterElectricSewage: "(підключення води, електрики, каналізації)",
    craneTruck: "Автокран для розвантаження",
    requiredForPlacement: "необхідний для розміщення будинку на ділянці",
    modularAdvantage: "Перевага модульної конструкції:",
    modularAdvantageDesc: "Цей будинок є ідеальним вибором для тих, хто шукає практичне, але стильне житло з простим монтажем та негайною готовністю до використання. Завдяки продуманому дизайну, якісним матеріалам та можливостям налаштування, він підходить як для менших родин, так і для людей, які шукають спокійне місце для відпочинку за містом.\n\nЦіна не включає транспортування, фундамент, зовнішні підключення та послуги крана, необхідні для розвантаження будинку.\n\nВсі наші будинки розроблені таким чином, щоб їх можна було легко транспортувати по всій ЄС у повністю завершеному стані. Після доставки клієнт просто розвантажує будинок з крана, встановлює його на підготовлений фундамент (одномодульні будинки не потребують міцного фундаменту), підключає комунікації та може негайно почати використовувати. Єдине, що залишається, це привезти улюблені меблі та обладнання за власним смаком.\n\nЦі будинки є ідеальним вибором для родин, які шукають практичне, негайно придатне для проживання рішення з можливістю мобільності. Вони також є чудовою альтернативою для пенсіонерів, які прагнуть затишного місця за містом – ідеального для відпочинку та комфортного проживання.\n\nЗавдяки якісним матеріалам, економним рішенням та простому плануванню, цей будинок розроблений таким чином, щоб задовольнити потреби кожного, хто шукає комфортний і водночас доступний спосіб життя.\n\nВнутрішній поділ кімнат, тип зовнішньої штукатурки та внутрішнього обшивання стін можна вільно змінювати.",
    
